43	/// The single synthetic fixture account.
44	pub const ACCOUNT_ID: &str = "fixture-account";
45	/// The fixture's primary mailbox, shared by reader/reply/account metadata.
46	pub const FIXTURE_MAILBOX: &str = "you@fixture.emailos";
47	
48	/// Generous shutdown budget; a paused fake provider is cancelled long before
49	/// this expires. If the join still times out the thread detaches, and the
50	/// interrupted operation stays durable for the next launch.
51	const STOP_JOIN_TIMEOUT: Duration = Duration::from_secs(5);
52	
53	type Listener = Arc<dyn Fn() + Send + Sync>;
54	
55	/// Shared listener registry. Kept separate from the core's inner state so the
56	/// worker's notify closure never creates a reference cycle.
57	struct ListenerHub {
58	    listeners: Mutex<HashMap<u64, Listener>>,
59	}
60	
61	/// Cloneable, thread-safe facade. Cheap to hold from a thin async Tauri
62	/// shell; blocking store calls stay inside [`MailCore`] methods so the shell
63	/// can wrap them in a blocking boundary.
64	pub struct MailCore {
65	    inner: Arc<Inner>,
66	}
67	
68	struct Inner {
69	    store: Arc<Store>,
70	    /// Profile lock is owned for the full core lifetime, and additionally
71	    /// shared with the worker thread: a detached or still-running worker can
72	    /// never outlive the lock (a second writer is rejected instead of two
73	    /// processes corrupting the database).
74	    profile: Arc<ProfileGuard>,
75	    hub: Arc<ListenerHub>,
76	    next_listener_id: AtomicU64,
77	    signal: Arc<WorkerSignal>,
78	    cancel: CancelToken,
79	    worker: Mutex<Option<std::thread::JoinHandle<()>>>,
80	    /// Queryable error surfaced when the worker halted on persistence failure.
81	    halt_sink: Arc<Mutex<Option<MailError>>>,
82	}
83	
84	impl Clone for MailCore {
85	    fn clone(&self) -> Self {
86	        Self {
87	            inner: Arc::clone(&self.inner),
88	        }
89	    }
90	}
