92	impl MailCore {
93	    /// Opens (or creates) the synthetic profile storage under `profile_dir`,
94	    /// acquires the profile lock for the full core lifetime, migrates, seeds
95	    /// the 18 synthetic conversations exactly once, and requeues interrupted
96	    /// `applying` operations in original sequence.
97	    pub fn open(profile_dir: impl AsRef<Path>) -> Result<MailCore, MailError> {
98	        Self::open_with_clock(profile_dir, Arc::new(clock::SystemClock))
99	    }
100	
101	    /// Like [`Self::open`] with an injectable clock; tests inject
102	    /// [`clock::FakeClock`] for deterministic undo-window behavior.
103	    pub fn open_with_clock(
104	        profile_dir: impl AsRef<Path>,
105	        clock: Arc<dyn clock::Clock>,
106	    ) -> Result<MailCore, MailError> {
107	        let profile_dir = profile_dir.as_ref();
108	        let profile = Arc::new(ProfileGuard::acquire(profile_dir)?);
109	        let store = Arc::new(Store::open(profile_dir, clock)?);
110	        store.recover_applying()?;
111	        let hub = Arc::new(ListenerHub {
112	            listeners: Mutex::new(HashMap::new()),
113	        });
114	        let halt_sink = Arc::new(Mutex::new(None));
115	        Ok(MailCore {
116	            inner: Arc::new(Inner {
117	                store,
118	                profile,
119	                hub,
120	                next_listener_id: AtomicU64::new(1),
121	                signal: Arc::new(WorkerSignal::new()),
122	                cancel: CancelToken::default(),
123	                worker: Mutex::new(None),
124	                halt_sink,
125	            }),
126	        })
127	    }
