248	    /// Starts the single serial worker. The provider is injected by the
249	    /// caller (the shell uses [`FakeArchiveProvider::from_env`]). Starting
250	    /// twice is rejected; it is not a valid request field, but the shell
251	    /// treats `invalid_request` with field `worker` as a programming bug.
252	    pub fn start_worker(&self, provider: Arc<dyn ArchiveProvider>) -> Result<(), MailError> {
253	        let mut worker = self
254	            .inner
255	            .worker
256	            .lock()
257	            .map_err(|_| MailError::StorageUnavailable)?;
258	        if worker.is_some() {
259	            return Err(MailError::InvalidRequest {
260	                field: "worker".to_string(),
261	            });
262	        }
263	        *self
264	            .inner
265	            .halt_sink
266	            .lock()
267	            .map_err(|_| MailError::StorageUnavailable)? = None;
268	        let handle = worker::spawn(
269	            Arc::clone(&self.inner.store),
270	            provider,
271	            Arc::clone(&self.inner.signal),
272	            self.inner.cancel.clone(),
273	            {
274	                let hub = Arc::clone(&self.inner.hub);
275	                Arc::new(move || dispatch(&hub)) as Notify
276	            },
277	            {
278	                let sink = Arc::clone(&self.inner.halt_sink);
279	                let hub = Arc::clone(&self.inner.hub);
280	                Arc::new(move |err| {
281	                    *sink.lock().expect("halt sink poisoned") = Some(err);
282	                    dispatch(&hub);
283	                }) as Arc<dyn Fn(MailError) + Send + Sync>
284	            },
285	            Arc::clone(&self.inner.profile),
286	        );
287	        *worker = Some(handle);
288	        Ok(())
289	    }
290	
291	    /// Requests worker shutdown, cancels a paused provider call, and joins
292	    /// the worker thread. Interrupted work stays durable (`applying`) and is
293	    /// requeued on next open.
294	    pub fn stop_worker(&self) {
295	        self.inner.shutdown_worker();
296	    }
297	
298	    /// Whether the worker thread is running.
299	    pub fn is_worker_running(&self) -> bool {
300	        self.inner
301	            .worker
302	            .lock()
303	            .map(|slot| slot.as_ref().is_some_and(|h| !h.is_finished()))
304	            .unwrap_or(false)
305	    }
306	
307	    /// Queryable error indication: set when the worker halted on persistence
308	    /// failure, cleared when the worker restarts. The shell surfaces this in
309	    /// its error state without a DTO change.
310	    pub fn worker_error(&self) -> Option<MailError> {
311	        self.inner
312	            .halt_sink
313	            .lock()
314	            .ok()
315	            .and_then(|sink| sink.clone())
316	    }
317	
318	    /// Registers a change listener and returns an unsubscribe handle. The
319	    /// listener fires after commits (receipts, confirmations, failures) and
320	    /// worker halts; it is a change hint, not a payload.
321	    pub fn subscribe(&self, listener: impl Fn() + Send + Sync + 'static) -> Unsubscribe {
322	        let id = self.inner.next_listener_id.fetch_add(1, Ordering::SeqCst);
323	        self.inner
324	            .hub
325	            .listeners
326	            .lock()
327	            .expect("listener hub poisoned")
328	            .insert(id, Arc::new(listener));
329	        Unsubscribe {
330	            id,
331	            hub: Arc::clone(&self.inner.hub),
332	        }
333	    }
334	
335	    fn ensure_worker_healthy(&self) -> Result<(), MailError> {
336	        let halt = self
337	            .inner
338	            .halt_sink
339	            .lock()
340	            .map_err(|_| MailError::StorageUnavailable)?;
341	        match halt.as_ref() {
342	            Some(error) => Err(error.clone()),
343	            None => Ok(()),
344	        }
345	    }
346	
347	    fn dispatch(&self) {
348	        dispatch(&self.inner.hub);
349	    }
350	}
