352	/// Removes the listener when unsubscribed or dropped.
353	#[must_use = "retain this guard for as long as change notifications are needed"]
354	pub struct Unsubscribe {
355	    id: u64,
356	    hub: Arc<ListenerHub>,
357	}
358	
359	impl Unsubscribe {
360	    pub fn unsubscribe(self) {
361	        // Removal happens in Drop.
362	    }
363	}
364	
365	impl Drop for Unsubscribe {
366	    fn drop(&mut self) {
367	        self.hub
368	            .listeners
369	            .lock()
370	            .expect("listener hub poisoned")
371	            .remove(&self.id);
372	    }
373	}
374	
375	fn dispatch(hub: &ListenerHub) {
376	    let listeners: Vec<Listener> = {
377	        let map = hub.listeners.lock().expect("listener hub poisoned");
378	        map.values().cloned().collect()
379	    };
380	    for listener in listeners {
381	        listener();
382	    }
383	}
384	
385	impl Inner {
386	    /// RAII shutdown: cancel the provider call, request stop, join the
387	    /// worker. Runs both from explicit [`MailCore::stop_worker`] and from
388	    /// `Drop` so dropping the core never leaves a worker running. If the
389	    /// join times out, the worker detaches while still holding its own
390	    /// reference to the profile lock, so storage stays exclusively owned.
391	    fn shutdown_worker(&self) {
392	        self.cancel.cancel();
393	        self.signal.request_stop();
394	        let handle = self.worker.lock().ok().and_then(|mut slot| slot.take());
395	        if let Some(handle) = handle {
396	            let deadline = Instant::now() + STOP_JOIN_TIMEOUT;
397	            while !handle.is_finished() {
398	                if Instant::now() >= deadline {
399	                    // Detach; the cancelled operation stays durable and the
400	                    // worker keeps holding the profile lock until it exits.
401	                    return;
402	                }
403	                std::thread::sleep(Duration::from_millis(5));
404	            }
405	            let _ = handle.join();
406	        }
407	    }
408	}
409	
410	impl Drop for Inner {
411	    fn drop(&mut self) {
412	        self.shutdown_worker();
413	    }
414	}
