420	    #[test]
421	    fn worker_halt_remains_visible_through_commands_after_storage_recovers() {
422	        let dir = std::env::temp_dir().join(format!("mail-core-halt-{}", uuid::Uuid::new_v4()));
423	        let core = MailCore::open(&dir).unwrap();
424	        let (tx, rx) = std::sync::mpsc::channel();
425	        let _subscription = core.subscribe(move || {
426	            let _ = tx.send(());
427	        });
428	        core.inner.store.set_test_persistence_failure(true);
429	        core.start_worker(Arc::new(FakeArchiveProvider::new()))
430	            .unwrap();
431	        rx.recv_timeout(Duration::from_secs(2))
432	            .expect("worker halt notification");
433	        core.inner.store.set_test_persistence_failure(false);
434	
435	        // The underlying DB is readable again, but the worker is still halted.
436	        assert!(core.inner.store.list_snapshot().is_ok());
437	        let target = ConversationRef {
438	            account_id: ACCOUNT_ID.into(),
439	            conversation_id: "conv-01".into(),
440	        };
441	        assert_eq!(
442	            core.list_conversations(),
443	            Err(MailError::StorageUnavailable)
444	        );
445	        assert_eq!(
446	            core.get_conversation(&target),
447	            Err(MailError::StorageUnavailable)
448	        );
449	        assert_eq!(
450	            core.set_archived(&SetArchived {
451	                conversation: target,
452	                archived: true,
453	                request_id: "after-halt".into(),
454	            }),
455	            Err(MailError::StorageUnavailable)
456	        );
457	        assert!(core
458	            .inner
459	            .store
460	            .list_snapshot()
461	            .unwrap()
462	            .activity
463	            .is_empty());
464	        drop(core);
465	        let restarted = MailCore::open(&dir).unwrap();
466	        assert!(restarted.list_conversations().is_ok());
467	        drop(restarted);
468	        std::fs::remove_dir_all(dir).unwrap();
469	    }
