471	    /// Core forwarding for the UX-05 group path (docs/ux-05-safe-bulk-processing.md
472	    /// §4): the accepted group's children execute serially through the
473	    /// unchanged worker, the group lookup reflects statuses, and the one-shot
474	    /// group Undo dispatches compensation immediately.
475	    #[test]
476	    fn group_children_execute_serially_and_group_undo_compensates() {
477	        let dir = std::env::temp_dir().join(format!("mail-core-group-{}", uuid::Uuid::new_v4()));
478	        let core = MailCore::open(&dir).unwrap();
479	        core.start_worker(Arc::new(FakeArchiveProvider::new()))
480	            .unwrap();
481	        let receipt = core
482	            .set_archived_group(&crate::groups::SetArchivedGroup {
483	                account_id: ACCOUNT_ID.into(),
484	                members: vec![
485	                    ConversationRef {
486	                        account_id: ACCOUNT_ID.into(),
487	                        conversation_id: "conv-01".into(),
488	                    },
489	                    ConversationRef {
490	                        account_id: ACCOUNT_ID.into(),
491	                        conversation_id: "conv-02".into(),
492	                    },
493	                ],
494	                archived: true,
495	                request_id: "core-group-1".into(),
496	            })
497	            .expect("group accepted");
498	        assert!(
499	            core.set_archived_group(&crate::groups::SetArchivedGroup {
500	                account_id: ACCOUNT_ID.into(),
501	                members: vec![
502	                    ConversationRef {
503	                        account_id: ACCOUNT_ID.into(),
504	                        conversation_id: "conv-02".into()
505	                    },
506	                    ConversationRef {
507	                        account_id: ACCOUNT_ID.into(),
508	                        conversation_id: "conv-01".into()
509	                    },
510	                ],
511	                archived: true,
512	                request_id: "core-group-1".into(),
513	            })
514	            .is_ok(),
515	            "reordered replay is the same request"
516	        );
517	        let child_ids: Vec<String> = receipt
518	            .members
519	            .iter()
520	            .map(|m| m.operation_id.clone().unwrap())
521	            .collect();
522	        // Both members execute serially through the worker.
523	        assert!(wait_for(|| {
524	            core.list_conversations()
525	                .unwrap()
526	                .activity
527	                .iter()
528	                .all(|row| {
529	                    !child_ids.contains(&row.id) || row.status == dto::OperationStatus::Confirmed
530	                })
531	        }));
532	        let status = core
533	            .get_operation_group(&crate::groups::GetOperationGroupRequest {
534	                account_id: ACCOUNT_ID.into(),
535	                request_id: "core-group-1".into(),
536	            })
537	            .unwrap()
538	            .expect("committed group");
539	        assert!(status
540	            .members
541	            .iter()
542	            .all(|m| m.status == crate::groups::GroupMemberStatus::Confirmed));
543	        assert!(status.undo.available, "inside the 10 s window");
544	
545	        // One-shot group Undo: compensation dispatches immediately.
546	        let undo = core
547	            .undo_operation_group(&crate::groups::UndoOperationGroup {
548	                group_id: receipt.group_id.clone(),
549	                request_id: "core-undo-group-1".into(),
550	            })
551	            .expect("group undo");
552	        assert!(undo
553	            .members
554	            .iter()
555	            .all(|m| m.decision == crate::groups::GroupMemberUndoDecision::Compensating));
556	        let compensations: Vec<String> = undo
557	            .members
558	            .iter()
559	            .flat_map(|m| m.operation_ids.clone())
560	            .collect();
561	        assert_eq!(compensations.len(), 2);
562	        assert!(wait_for(|| {
563	            core.list_conversations()
564	                .unwrap()
565	                .activity
566	                .iter()
567	                .all(|row| {
568	                    !compensations.contains(&row.id)
569	                        || row.status == dto::OperationStatus::Confirmed
570	                })
571	        }));
572	        // Restored overlays: both conversations are back in the inbox.
573	        let snapshot = core.list_conversations().unwrap();
574	        for conversation_id in ["conv-01", "conv-02"] {
575	            assert!(snapshot
576	                .conversations
577	                .iter()
578	                .any(|c| c.conversation_ref.conversation_id == conversation_id));
579	        }
580	        // Restart: the group, member outcomes and receipt replay survive.
581	        core.stop_worker();
582	        drop(core);
583	        let reopened = MailCore::open(&dir).unwrap();
584	        assert_eq!(
585	            reopened
586	                .set_archived_group(&crate::groups::SetArchivedGroup {
587	                    account_id: ACCOUNT_ID.into(),
588	                    members: vec![
589	                        ConversationRef {
590	                            account_id: ACCOUNT_ID.into(),
591	                            conversation_id: "conv-01".into()
592	                        },
593	                        ConversationRef {
594	                            account_id: ACCOUNT_ID.into(),
595	                            conversation_id: "conv-02".into()
596	                        },
597	                    ],
598	                    archived: true,
599	                    request_id: "core-group-1".into(),
600	                })
601	                .unwrap(),
602	            receipt,
603	            "same request replays the original receipt after restart"
604	        );
605	        let status = reopened
606	            .get_operation_group(&crate::groups::GetOperationGroupRequest {
607	                account_id: ACCOUNT_ID.into(),
608	                request_id: "core-group-1".into(),
609	            })
610	            .unwrap()
611	            .expect("group survives restart");
612	        assert_eq!(
613	            status.undo.reason,
614	            Some(dto::UndoUnavailableReason::AlreadyUndone),
615	            "group undo outcome survives restart"
616	        );
617	        drop(reopened);
618	        std::fs::remove_dir_all(dir).unwrap();
619	    }
620	
621	    fn wait_for(predicate: impl Fn() -> bool) -> bool {
622	        let deadline = Instant::now() + Duration::from_secs(5);
623	        while !predicate() {
624	            if Instant::now() >= deadline {
625	                return predicate();
626	            }
627	            std::thread::sleep(Duration::from_millis(10));
628	        }
629	        true
630	    }
631	}
