431	/// Managed app state retains its change-listener guard for the full app life.
432	#[derive(Default)]
433	struct AttachmentTransfers {
434	    active: HashMap<String, CancelToken>,
435	    cancelled: VecDeque<String>,
436	}
437	impl AttachmentTransfers {
438	    fn begin(&mut self, id: &str) -> Result<CancelToken, MailError> {
439	        if !mail_core::attachments::valid_id(id) {
440	            return Err(mail_core::attachments::invalid("requestId"));
441	        }
442	        if !self.active.is_empty() {
443	            return Err(MailError::Busy);
444	        }
445	        if self.cancelled.iter().any(|v| v == id) {
446	            return Err(MailError::AuthCancelled);
447	        }
448	        let token = CancelToken::default();
449	        self.active.insert(id.into(), token.clone());
450	        Ok(token)
451	    }
452	    fn cancel(&mut self, id: &str) {
453	        if let Some(token) = self.active.get(id) {
454	            token.cancel();
455	        }
456	        self.cancelled.push_back(id.into());
457	        while self.cancelled.len() > 64 {
458	            self.cancelled.pop_front();
459	        }
460	    }
461	}
