539	/// Run all synchronous core/storage operations outside Tauri's async/UI threads.
540	async fn run_blocking<T, F>(backend: Backend, f: F) -> Result<T, MailError>
541	where
542	    F: FnOnce(&Backend) -> Result<T, MailError> + Send + 'static,
543	    T: Send + 'static,
544	{
545	    tauri::async_runtime::spawn_blocking(move || f(&backend))
546	        .await
547	        .map_err(|_| MailError::StorageUnavailable)?
548	}
