957	#[tauri::command]
958	async fn create_draft(
959	    app: AppHandle,
960	    state: State<'_, AppState>,
961	    command: CreateDraft,
962	) -> Result<DraftReceipt, MailError> {
963	    let backend = state.backend.clone();
964	    let drafts = state.drafts.clone();
965	    let lifecycle = Arc::clone(&state.draft_lifecycle);
966	    let receipt = run_blocking(backend, move |backend| {
967	        let lifecycle_guard = lifecycle
968	            .lock()
969	            .map_err(|_| MailError::StorageUnavailable)?;
970	        let account = active_account(backend)?;
971	        if let Some(receipt) = drafts.lookup_create_receipt(&account, &command)? {
972	            return Ok(receipt);
973	        }
974	        match &command.source {
975	            DraftSource::NewMessage => drafts.create_draft(&account, &command, None),
976	            DraftSource::Reply {
977	                conversation,
978	                source_message_id,
979	            } => {
980	                if conversation.account_id != account.account_id {
981	                    return Err(MailError::ReplyUnavailable);
982	                }
983	                let displayed = backend.get_conversation(conversation)?;
984	                validate_reply_conversation(&displayed, conversation, source_message_id)?;
985	                let session_epoch = lifecycle_guard.session_epoch;
986	                drop(lifecycle_guard);
987	
988	                // This helper is a cache hit when metadata is ready. A legacy
989	                // metadata fetch is readonly and deliberately happens unlocked.
990	                let reply_conversation =
991	                    backend.load_reply_context(conversation, source_message_id)?;
992	
993	                let lifecycle_guard = lifecycle
994	                    .lock()
995	                    .map_err(|_| MailError::StorageUnavailable)?;
996	                if !lifecycle_guard.is_current(session_epoch)
997	                    || active_account(backend)?.account_id != account.account_id
998	                {
999	                    return Err(MailError::AuthRequired);
1000	                }
1001	                let current = backend.get_conversation(conversation)?;
1002	                validate_reply_conversation(&current, conversation, source_message_id)?;
1003	                if current.reply_context != reply_conversation.reply_context {
1004	                    return Err(MailError::ReplyUnavailable);
1005	                }
1006	                drafts.create_draft(&account, &command, Some(&reply_conversation))
1007	            }
1008	        }
1009	    })
1010	    .await?;
1011	    let _ = app.emit("drafts_changed", ());
1012	    Ok(receipt)
1013	}
