1109	    static NEXT_CLOSE_ID: AtomicU64 = AtomicU64::new(1);
1110	    let timestamp = SystemTime::now()
1111	        .duration_since(UNIX_EPOCH)
1112	        .map(|duration| duration.as_nanos())
1113	        .unwrap_or_default();
1114	    format!(
1115	        "{:x}-{:x}-{:x}",
1116	        std::process::id(),
1117	        timestamp,
1118	        NEXT_CLOSE_ID.fetch_add(1, Ordering::Relaxed)
1119	    )
1120	}
